function countGoodSeatings(n: number): number {
  const used = new Array(n + 1).fill(false);
  const place = (seat: number): number => {
    if (seat === 0) return 1;
    let total = 0;
    for (let g = 1; g <= n; g++) {
      if (used[g] || (g % seat !== 0 && seat % g !== 0)) continue;
      used[g] = true;
      total += place(seat - 1);
      used[g] = false;
    }
    return total;
  };
  return place(n);
}

