function countGoodSeatings(n: number): number {
  const ways = new Array(1 << n).fill(0);
  ways[0] = 1;
  for (let mask = 0; mask < 1 << n; mask++) {
    if (!ways[mask]) continue;
    let seat = 1;
    for (let m = mask; m; m &= m - 1) seat++; // next seat = guests seated + 1
    for (let g = 1; g <= n; g++) {
      const bit = 1 << (g - 1);
      if (mask & bit) continue;
      if (g % seat === 0 || seat % g === 0) ways[mask | bit] += ways[mask];
    }
  }
  return ways[(1 << n) - 1];
}

