        ways[0] = 1
        for mask in range(1 << n):
            if not ways[mask]:
                continue
            seat = bin(mask).count("1") + 1  # next seat to fill
            for g in range(1, n + 1):
                bit = 1 << (g - 1)
                if not mask & bit and (g % seat == 0 or seat % g == 0):
                    ways[mask | bit] += ways[mask]
